theorem roughPower_cutoffs {D epsilon r : ℝ}
    (hD : 1 < D) (hepsilon : 0 < epsilon) (hepsilonr : epsilon ^ 2 ≤ r) :
    1 < D ^ (epsilon ^ 2) ∧ D ^ (epsilon ^ 2) ≤ D ^ r

